import { useAliases } from '../aliases/aliases';
import type { Alias } from '../aliases/aliases';
import { useClaims } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { personOverdue } from '../overdue/overdue';
import { liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDue, trimmedTotal, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import type { DueRules } from '../settings/settings';
import { useCurrentUser } from '../session/session';

/** The statuses counted, as in the summary; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

/** A sheet's due-total and overdue-total as its header shows them. */
export function sheetTotals(people: Person[], claims: Claim[], rates: Rate[], rules: DueRules): { due: string; overdue: string } {
  const mine = (id: number) => claims.filter((c) => c.personId === id);
  const dues = people.map((p) => personDue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules));
  const overdue = people.map((p) => personOverdue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules).total);
  return { due: trimmedTotal(dues), overdue: trimmedTotal(overdue) };
}

/** A name as names are compared: trimmed, ignoring case. */
const nameKey = (name: string) => name.trim().toLowerCase();

/** The person on the sheet with the user's name, by name or alias, if any. */
export function personNamed(people: Person[], aliases: Alias[], user: string): Person | undefined {
  const key = nameKey(user);
  if (!key) return undefined;
  return (
    people.find((p) => nameKey(p.name) === key) ??
    people.find((p) => aliases.some((a) => a.personId === p.id && nameKey(a.alias) === key))
  );
}

// The sheet's counters, always in the header: everyone on it (retired people included), its claims per
// status, its due-total and overdue-total, and the signed-in user's own (blank when no one on it has their name) — each worked out exactly as the figure it repeats.
export function HeaderCounters() {
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const aliases = useAliases().data ?? [];
  const [user] = useCurrentUser();

  const me = personNamed(people, aliases, user ?? '');
  const mine = me ? claims.filter((c) => c.personId === me.id) : [];
  const myDue = me ? personDue(mine, rates, me.grades, liveHolds(me, rules.today), rules) : '';
  const myOverdue = me ? personOverdue(mine, rates, me.grades, liveHolds(me, rules.today), rules).total : '';
  const totals = sheetTotals(people, claims, rates, rules);
  return (
    <p data-testid="header-counters">
      People: <strong data-testid="header-people-count">{people.length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <strong data-testid={`header-claims-${s}-count`}>{claims.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      {' · '}Due: <strong data-testid="header-due-total">{totals.due}</strong>
      {' · '}Overdue: <strong data-testid="header-overdue-total">{totals.overdue}</strong>
      {' · '}Mine: <strong data-testid="my-due-total">{myDue}</strong>
      {' / '}<strong data-testid="my-overdue-total">{myOverdue}</strong>
    </p>
  );
}
import { AppHeader } from '../../slots/defs/appHeader';
import { HeaderCounters } from './HeaderCounters';

export const contribution = AppHeader.fill({ order: 30, Component: HeaderCounters });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { crewDue, crewsKey, useCrews, useDueByPerson } from './crews';
import type { Crew } from './crews';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's crews, each with its lead and due-total, and the form that adds one; a blank name, one already a
// crew's, or no lead chosen, is refused.
export function Crews() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const crews = useCrews().data ?? [];
  const people = usePeople().data ?? [];
  const dueOf = useDueByPerson();
  const [name, setName] = useState('');
  const [lead, setLead] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { name: string; leadId: number }) =>
      postJson<Crew[]>(`/api/sheets/${encodeURIComponent(sheet)}/crews?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setName('');
      setLead('');
      setError('');
      queryClient.setQueryData(crewsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: crewsKey(sheet) });
    },
    onError: () => setError('That crew was refused: it needs a name no other crew has and a lead on the sheet.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const trimmed = name.trim();
    if (!trimmed) {
      setError('Type the crew name.');
      return;
    }
    if (crews.some((c) => c.name === trimmed)) {
      setError(`There is already a crew named ${trimmed}.`);
      return;
    }
    if (!lead) {
      setError('Choose the crew lead.');
      return;
    }
    once(() => add.mutateAsync({ name, leadId: Number(lead) }));
  };

  return (
    <section data-testid="crews">
      <ul data-testid="crew-list">
        {crews.map((c) => (
          <CrewRow key={c.id} crew={c} due={crewDue(c, dueOf)} />
        ))}
      </ul>
      <form onSubmit={submit} data-testid="crew-form">
        <input
          data-testid="crew-form-name"
          placeholder="Crew name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
        <select
          data-testid="crew-form-lead"
          value={lead}
          onChange={(e) => {
            setLead(e.target.value);
            setError('');
          }}
        >
          <option value="">Choose a lead</option>
          {people.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>
        <button type="submit" data-testid="crew-form-submit" disabled={add.isPending}>
          Add crew
        </button>
        {error && <span data-testid="crew-form-error">{error}</span>}
      </form>
    </section>
  );
}

// A crew's row: its lead, its members and its due-total, and the form that adds a member — the lead, or a person
// already in the crew, is refused.
function CrewRow({ crew, due }: { crew: Crew; due: string }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const [member, setMember] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: { personId: number }) =>
      postJson<Crew[]>(
        `/api/sheets/${encodeURIComponent(sheet)}/crews/${crew.id}/members?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (saved) => {
      setMember('');
      setError('');
      queryClient.setQueryData(crewsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: crewsKey(sheet) });
    },
    onError: () => setError('That member was refused: a person on the sheet, not the lead and not yet in the crew.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!member) {
      setError('Choose a person.');
      return;
    }
    const id = Number(member);
    if (id === crew.lead.id) {
      setError('That person leads the crew.');
      return;
    }
    if (crew.members.some((m) => m.id === id)) {
      setError('That person is already in the crew.');
      return;
    }
    once(() => add.mutateAsync({ personId: id }));
  };

  return (
    <li data-testid={`crew-row-${crew.name}`}>
      <span data-testid="crew-name">{crew.name}</span> lead <span data-testid="crew-lead">{crew.lead.name}</span>{' '}
      due-total <span data-testid="crew-due-total">{due}</span>
      <ul>
        {crew.members.map((m) => (
          <li key={m.id} data-testid="crew-member-line">
            <span data-testid="crew-member-name">{m.name}</span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="crew-member-select"
          value={member}
          onChange={(e) => {
            setMember(e.target.value);
            setError('');
          }}
        >
          <option value="">Choose a person</option>
          {people.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>
        <button type="submit" data-testid="crew-member-add" disabled={add.isPending}>
          Add member
        </button>
        {error && <span data-testid="crew-error">{error}</span>}
      </form>
    </li>
  );
}
